fn two_sum(nums: &Vec<u32>, target: u32) -> (usize, usize) {
    let n = nums.len();
    // Iterate in lexicographic order: first index increasing,
    // then second index increasing
    for i in 0..n {
        for j in (i + 1)..n {
            if nums[i] + nums[j] == target {
                return (i, j);
            }
        }
    }
    // By assumption, there is always at least one valid pair.
    unreachable!("No valid two-sum pair found");
}

